function buildGreenwood() {
  const m = make(38, 26, '.');
  const rng = mulberry32(421);
  border(m, '#', 2);
  scatter(m, '#', 55, rng);
  scatter(m, 'T', 18, rng);
  scatter(m, '"', 48, rng);
  scatter(m, ',', 40, rng);
  scatter(m, 'r', 8, rng);

  // portals
  rect(m, 0, 11, 3, 4, '_');
  put(m, 0, 13, 'P');
  rect(m, 18, 0, 5, 3, '_');
  put(m, 20, 0, 'P');

  // main trails
  hline(m, 1, 19, 13, '_', 2);
  hline(m, 19, 24, 13, '_', 2);
  vline(m, 20, 1, 12, '_', 2);
  vline(m, 21, 14, 25, '_', 2);
  // grove ring
  rect(m, 16, 10, 8, 7, '.');
  outline(m, 16, 10, 8, 7, '"');
  put(m, 19, 10, 'A'); put(m, 20, 10, '.'); put(m, 19, 11, '.'); put(m, 20, 11, '.');
  rect(m, 18, 16, 4, 2, '_');
  // trails to Mosswood
  hline(m, 5, 16, 11, '_', 2);
  vline(m, 6, 12, 12, '_', 1);
  // trails to Warden camp
  hline(m, 24, 29, 11, '_', 2);
  vline(m, 29, 7, 12, '_', 1);
  // trails to Freewood
  hline(m, 22, 29, 20, '_', 2);
  vline(m, 29, 21, 22, '_', 1);

  // Mosswood village
  house(m, 4, 4, 6, 4);   // inn
  house(m, 11, 4, 5, 4);  // shop
  house(m, 5, 16, 5, 4);  // cottage
  rect(m, 3, 9, 12, 3, '=');
  put(m, 10, 9, 'o'); put(m, 14, 9, 'L');
  put(m, 3, 8, 'f'); put(m, 15, 8, 'f');
  put(m, 8, 7, 'i');
  rect(m, 17, 4, 5, 3, ',');
  put(m, 18, 3, 't'); put(m, 21, 3, 't');

  // Warden camp
  rect(m, 25, 4, 9, 7, '.');
  tents(m, 26, 5, 3, 2); tents(m, 30, 6, 3, 2);
  put(m, 25, 8, 'o'); put(m, 32, 4, 'L');
  hline(m, 25, 33, 10, 'f'); put(m, 29, 10, '_');
  put(m, 32, 9, 'C');
  put(m, 27, 9, 'i');

  // Freewood grove
  rect(m, 24, 18, 9, 5, '.');
  scatter(m, 'T', 5, rng, { x: 24, y: 18, w: 9, h: 5 }, ['.']);
  tents(m, 26, 19, 3, 2); tents(m, 31, 20, 2, 2);
  put(m, 29, 22, 'o');
  put(m, 25, 22, 'i');

  // features
  put(m, 36, 8, 'C');
  put(m, 33, 16, 'C');
  put(m, 2, 22, 'C');
  put(m, 35, 24, 'o');
  put(m, 8, 21, 'S');

  // extra clearings
  rect(m, 20, 13, 2, 2, '_');
  hline(m, 19, 22, 13, '_');
  // clear spawn/portals
  rect(m, 0, 12, 3, 3, '_'); put(m, 0, 13, 'P');
  put(m, 20, 0, 'P'); rect(m, 18, 0, 5, 3, '_');
  return m;
}

// ═══════════════════════════════════════════════════════════════
// ASHEN MIRE — drowned shrine and the witch's hut
// ═══════════════════════════════════════════════════════════════
function buildMire() {
  const m = make(36, 26, '.');
  const rng = mulberry32(8803);
  border(m, '#', 2);
  // water bog
  for (let i = 0; i < 22; i++) {
    const cx = 3 + Math.floor(rng() * 29), cy = 3 + Math.floor(rng() * 19);
    const rw = 2 + Math.floor(rng() * 4), rh = 1 + Math.floor(rng() * 3);
    rect(m, cx, cy, rw, rh, rng() < .45 ? '~' : 'w');
  }
  scatter(m, 'T', 14, rng, null, ['.', 'w', '~']);
  scatter(m, '#', 22, rng);
  scatter(m, 'w', 18, rng, null, ['.']);
  scatter(m, '"', 20, rng);
  scatter(m, 't', 10, rng, null, ['.']);

  // north portal to Emberfield
  rect(m, 17, 0, 3, 4, 'b');
  put(m, 18, 0, 'P');
  // shrine island (west)
  rect(m, 5, 4, 10, 6, '=');
  outline(m, 5, 4, 10, 6, 'W');
  put(m, 5, 6, 'W'); put(m, 6, 9, 'W'); put(m, 14, 5, 'W');
  put(m, 9, 4, 'A'); put(m, 13, 8, 'S'); put(m, 6, 5, 'o'); put(m, 12, 4, 'o');
  put(m, 8, 10, '=');
  // witch hut (east)
  house(m, 26, 17, 6, 4);
  put(m, 25, 20, 'o'); put(m, 24, 21, 'i');
  rect(m, 24, 16, 9, 6, '.');
  // paths as boardwalks
  hline(m, 9, 18, 4, 'b', 1);
  vline(m, 18, 4, 14, 'b', 1);
  hline(m, 18, 26, 14, 'b', 1);
  hline(m, 22, 26, 20, 'b', 1);
  vline(m, 22, 14, 20, 'b', 1);
  hline(m, 9, 18, 10, 'b', 1);
  vline(m, 9, 10, 15, 'b', 1);
  hline(m, 9, 22, 15, 'b', 1);
  put(m, 15, 7, 'C');
  // islands and details
  rect(m, 15, 19, 6, 4, '.');
  scatter(m, 'g', 5, rng, { x: 15, y: 19, w: 6, h: 4 }, ['.']);
  put(m, 18, 21, 't');
  put(m, 31, 12, 'C');
  put(m, 5, 18, 'C');
  put(m, 33, 8, 'o');
  // clear portal lane
  rect(m, 17, 0, 3, 3, 'b'); put(m, 18, 0, 'P');
  return m;
}

// ═══════════════════════════════════════════════════════════════
// CINDER PEAKS — Ashen Order camp and the caldera
// ═══════════════════════════════════════════════════════════════
function buildPeaks() {
  const m = make(36, 26, '.');
  const rng = mulberry32(5519);
  // ash base with lava basins and mountains
  rect(m, 0, 0, 36, 26, 'x');
  border(m, '^', 2);
  // mountain ridges
  rect(m, 2, 2, 8, 3, '^');
  rect(m, 13, 2, 8, 2, '^');
  rect(m, 27, 2, 7, 5, '^');
  rect(m, 3, 10, 4, 4, '^');
  rect(m, 29, 10, 5, 6, '^');
  rect(m, 2, 22, 9, 2, '^');
  scatter(m, '^', 20, rng, null, ['x']);
  scatter(m, 'r', 18, rng, null, ['x']);
  scatter(m, 'B', 8, rng, null, ['x']);
  scatter(m, '"', 6, rng, null, ['x']);

  // lava river
  hline(m, 5, 34, 15, 'v', 1);
  hline(m, 7, 33, 16, 'v', 1);
  for (let i = 0; i < 10; i++) {
    const x = 5 + Math.floor(rng() * 28);
    put(m, x, 14, rng() < .5 ? 'v' : 'x');
    put(m, x, 17, rng() < .5 ? 'v' : 'x');
  }
  // bridges over lava
  rect(m, 9, 14, 2, 4, 'b');
  rect(m, 20, 14, 2, 4, 'b');
  rect(m, 28, 14, 2, 4, 'b');

  // south portal to Greenwood
  rect(m, 17, 23, 3, 3, '=');
  put(m, 18, 25, 'P');
  // east portal to Citadel
  rect(m, 33, 12, 3, 3, '=');
  put(m, 35, 13, 'P');

  // camp (west)
  rect(m, 5, 5, 9, 7, 'x');
  tents(m, 6, 6, 3, 2); tents(m, 10, 7, 3, 2);
  put(m, 9, 10, 'o'); put(m, 12, 5, 'L');
  hline(m, 5, 13, 11, 'f'); put(m, 9, 11, 'x');
  put(m, 13, 9, 'C');
  put(m, 5, 12, 'i');

  // caldera approach and shrine
  rect(m, 18, 3, 12, 10, '=');
  rect(m, 18, 3, 12, 1, 'W');
  rect(m, 18, 12, 12, 1, 'W');
  put(m, 22, 9, 'A'); put(m, 29, 7, 'A');
  put(m, 19, 4, 'o'); put(m, 28, 11, 'o'); put(m, 21, 11, 'o');
  put(m, 33, 5, 'C');
  // hot spring
  rect(m, 4, 17, 6, 4, 'w');
  outline(m, 3, 16, 8, 6, 'r');
  put(m, 5, 18, 'S'); put(m, 8, 20, 'S');
  // paths
  hline(m, 9, 18, 13, '=', 1);
  hline(m, 13, 20, 19, '=', 1);
  vline(m, 13, 12, 19, '=', 1);
  vline(m, 20, 13, 14, '=', 1);
  vline(m, 21, 18, 23, '=', 1);
  hline(m, 18, 22, 23, '=', 1);
  vline(m, 18, 24, 25, '=', 1);
  put(m, 15, 20, 'C');
  put(m, 30, 21, 'C');
  put(m, 10, 19, 'i');
  // clear portal paths
  rect(m, 17, 23, 3, 3, '='); put(m, 18, 25, 'P');
  rect(m, 33, 12, 3, 3, '='); put(m, 35, 13, 'P');
  put(m, 33, 14, '=');
  return m;
}

// ═══════════════════════════════════════════════════════════════
// HOLLOW CITADEL — the throne of ash
// ═══════════════════════════════════════════════════════════════
function buildCitadel() {
  const m = make(32, 22, 'W');
  const rng = mulberry32(13);
  // main hall
  rect(m, 2, 8, 12, 8, '=');
  rect(m, 12, 6, 8, 12, '=');
  rect(m, 14, 2, 5, 12, '=');
  rect(m, 4, 10, 6, 4, '=');
  rect(m, 20, 12, 8, 6, '=');
  // side halls
  rect(m, 2, 2, 6, 5, '=');
  rect(m, 24, 2, 6, 6, '=');
  // throne room
  rect(m, 12, 2, 9, 3, '=');
  rect(m, 13, 1, 7, 1, 'W');
  put(m, 16, 3, 'A');
  put(m, 13, 3, 'o'); put(m, 19, 3, 'o');
  // pillars
  for (const [x, y] of [[5, 9], [10, 9], [5, 14], [10, 14], [14, 7], [18, 7], [14, 16], [18, 16], [21, 13], [26, 13], [21, 17], [26, 17], [3, 4], [7, 4], [25, 4], [29, 4]]) put(m, x, y, 'L');
  // entrance
  rect(m, 0, 10, 3, 4, '=');
  put(m, 0, 11, 'P');
  put(m, 3, 11, 'S');
  // chests
  put(m, 6, 3, 'C');
  put(m, 28, 5, 'C');
  put(m, 27, 15, 'C');
  // dais carpet
  rect(m, 15, 4, 3, 12, '_');
  // rubble / ash
  scatter(m, 'r', 6, rng, { x: 2, y: 2, w: 28, h: 18 }, ['=']);
  scatter(m, 'B', 5, rng, { x: 2, y: 2, w: 28, h: 18 }, ['=']);
  // portal back
  rect(m, 0, 10, 3, 4, '='); put(m, 0, 11, 'P');
  return m;
}

