      ctx.fillStyle = acc;
      ctx.beginPath(); ctx.arc(-H * .04, foot - h, s * .018, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(H * .04, foot - h, s * .018, 0, TAU); ctx.fill();
      // weapon
      ctx.strokeStyle = '#cfc6b2'; ctx.lineWidth = s * .04;
