      ctx.moveTo(-H * .14, cy); ctx.lineTo(-H * .12, cy - H * .08); ctx.lineTo(-H * .06, cy - H * .03);
      ctx.lineTo(0, cy - H * .11); ctx.lineTo(H * .06, cy - H * .03); ctx.lineTo(H * .12, cy - H * .08); ctx.lineTo(H * .14, cy);
