  'Trader Quill': { role: 'merchant', palette: 0, color: '#c0a060' },
  'Captain Thea': { role: 'guard', palette: 1, color: '#9b8a6a' },
  'Elder Bramble': { role: 'elder', palette: 4, color: '#8fbf7a' },
