251:   const W = canvas.clientWidth, H = canvas.clientHeight;
252:   const T = tileScale(W, H);
253:   const wx = (cx + world.camx) / T;
254:   const wy = (cy + world.camy) / T;
255:   const tx = Math.floor(wx), ty = Math.floor(wy);
256:   let target = { x: tx, y: ty };
257:   const obj = interactables().find((o) => o.x === tx && o.y === ty);
258:   if (obj) {
259:     const adj = adjacentWalkable(tx, ty);
260:     if (!adj) { audio.sfx('error'); return; }
261:     target = adj;
262:     world.player.pending = obj;
263:   } else {
264:     world.player.pending = null;
265:   }
266:   if (!isWalkable(target.x, target.y)) {
267:     // find nearest walkable around tap within 1
268:     let best = null;
269:     for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
270:       if (isWalkable(tx + dx, ty + dy)) { best = { x: tx + dx, y: ty + dy }; break; }
271:     }
272:     if (!best) return;
273:     target = best;
274:   }
275:   if (obj) {
276:     const d = Math.abs(obj.x - world.player.x) + Math.abs(obj.y - world.player.y);
277:     if (d <= 1) { interactWith(obj); return; }
278:   }
279:   const path = findPath({ x: world.player.x, y: world.player.y }, target);
280:   if (path) {
281:     world.player.path = path;
282:     world.tapMarker = { x: target.x, y: target.y, at: performance.now() };
283:     audio.sfx('click');
284:   }
285: }
