352: function inputDirection() {
353:   const k = world.keys;
354:   let dx = 0, dy = 0;
355:   if (k.left) dx -= 1;
356:   if (k.right) dx += 1;
357:   if (k.up) dy -= 1;
358:   if (k.down) dy += 1;
359:   if (Math.hypot(world.joy.x, world.joy.y) > .38) { dx = world.joy.x; dy = world.joy.y; }
360:   if (!dx && !dy) return null;
361:   if (Math.abs(dx) > Math.abs(dy)) return dx > 0 ? 'right' : 'left';
362:   return dy > 0 ? 'down' : 'up';
363: }
