365: function tryMove(dir) {
366:   const p = world.player;
367:   const [dx, dy] = DIRS[dir];
368:   p.facing = dir;
369:   const nx = p.x + dx, ny = p.y + dy;
370:   if (!isWalkable(nx, ny)) {
371:     // little bump
372:     p.px = p.x + dx * .06; p.py = p.y + dy * .06;
373:     setTimeout(() => { if (!p.moving) { p.px = p.x; p.py = p.y; } }, 60);
374:     return false;
375:   }
376:   p.from = { x: p.x, y: p.y };
377:   p.to = { x: nx, y: ny };
378:   p.progress = 0;
379:   p.moving = true;
380:   if (Math.random() < .25) audio.sfx('step');
381:   return true;
382: }
