260: function drawEffect(ctx, eff, W, H, now, pos) {
261:   const age = now - eff.born;
262:   if (age < 0 || age > eff.dur) return;
263:   const k = age / eff.dur;
264:   const x = pos?.x ?? eff.x ?? W * .4;
