266:   const rare = 0;
267:   ctx.save();
268:   ctx.globalCompositeOperation = 'lighter';
269:   if (eff.kind === 'fire') {
270:     for (let i = 0; i < 16; i++) {
271:       const a = (i / 16) * TAU + age * .003;
272:       const d = Math.sin(k * Math.PI) * 52 + (i % 3) * 10;
273:       const px = x + Math.cos(a) * d;
274:       const py = y - 20 + Math.sin(a) * d * .6 - k * 34;
275:       ctx.fillStyle = `rgba(255,${120 + (i * 23 % 90)},50,${(1 - k) * .75})`;
276:       ctx.beginPath(); ctx.arc(px, py, (1 - k) * 7 + 1.5, 0, TAU); ctx.fill();
277:     }
278:     ctx.strokeStyle = `rgba(255,160,80,${(1 - k) * .8})`;
279:     ctx.lineWidth = 2;
280:     ctx.beginPath(); ctx.ellipse(x, y - 14, 18 + k * 60, 10 + k * 30, 0, 0, TAU); ctx.stroke();
281:   } else if (eff.kind === 'frost') {
282:     for (let i = 0; i < 12; i++) {
283:       const a = i / 12 * TAU;
284:       const d = 20 + k * 70;
285:       ctx.fillStyle = `rgba(160,230,255,${(1 - k) * .8})`;
286:       ctx.save(); ctx.translate(x + Math.cos(a) * d, y - 24 + Math.sin(a) * d * .5); ctx.rotate(a);
287:       ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(2.5, 0); ctx.lineTo(0, 7); ctx.lineTo(-2.5, 0); ctx.closePath(); ctx.fill();
288:       ctx.restore();
289:     }
290:   } else if (eff.kind === 'storm') {
291:     ctx.strokeStyle = `rgba(170,220,255,${(1 - k) * .95})`;
292:     ctx.lineWidth = 2.5;
293:     ctx.beginPath();
294:     let lx = x + (pos ? 0 : 0), ly = 0;
295:     ctx.moveTo(lx + (pos ? 0 : 0), 0);
296:     for (let i = 1; i <= 7; i++) {
297:       const yy = y * (i / 7) - 20;
298:       lx = x + (hash(i, Math.floor(eff.born / 100)) - .5) * 60;
299:       ctx.lineTo(lx, yy);
300:     }
301:     ctx.stroke();
302:     ctx.strokeStyle = `rgba(255,255,255,${(1 - k) * .5})`; ctx.lineWidth = 1; ctx.stroke();
303:   } else if (eff.kind === 'nature') {
304:     for (let i = 0; i < 18; i++) {
305:       const a = i / 18 * TAU;
306:       const d = k * 58;
307:       ctx.fillStyle = `rgba(150,220,120,${(1 - k) * .7})`;
308:       ctx.beginPath(); ctx.arc(x + Math.cos(a) * d, y - 25 + Math.sin(a) * d * .6, 2.5, 0, TAU); ctx.fill();
309:     }
310:   } else if (eff.kind === 'shadow') {
311:     const g = ctx.createRadialGradient(x, y - 25, 0, x, y - 25, 30 + k * 50);
312:     g.addColorStop(0, `rgba(150,110,200,${(1 - k) * .5})`);
313:     g.addColorStop(1, 'rgba(30,10,50,0)');
314:     ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 25, 30 + k * 50, 0, TAU); ctx.fill();
315:     for (let i = 0; i < 8; i++) {
316:       const a = i / 8 * TAU + k;
317:       ctx.strokeStyle = `rgba(120,80,160,${(1 - k) * .6})`;
318:       ctx.beginPath(); ctx.moveTo(x, y - 25); ctx.lineTo(x + Math.cos(a) * k * 70, y - 25 + Math.sin(a) * k * 50); ctx.stroke();
319:     }
320:   } else if (eff.kind === 'heal') {
321:     for (let i = 0; i < 14; i++) {
322:       const px = x + (hash(i, 7) - .5) * 50;
323:       const py = y - 10 - ((k + hash(i, 3)) % 1) * 70;
324:       ctx.fillStyle = `rgba(170,240,180,${(1 - k) * .8})`;
