            <div class="pr-meta"><span class="pr-class">${cls.name}</span> · L${m.level} · ${m.title ? escapeHtml(m.title) : cls.role}</div>
            <div class="pr-bars">
              <div class="pc-bar hp" style="height:4px"><i style="width:${Math.max(0, m.hp / st.maxHp * 100)}%"></i></div>
