73: export function statBlock(member) {
74:   const cls = CLASSES[member.classId];
75:   const lv = Math.max(1, member.level);
76:   const g = cls.grow, b = cls.base;
77:   const s = {
78:     hp: b.hp + g.hp * (lv - 1),
79:     mp: b.mp + g.mp * (lv - 1),
80:     atk: b.atk + g.atk * (lv - 1),
81:     def: b.def + g.def * (lv - 1),
82:     mag: b.mag + g.mag * (lv - 1),
83:     res: b.res + g.res * (lv - 1),
84:     agi: b.agi + g.agi * (lv - 1),
85:     luck: b.luck + g.luck * (lv - 1),
86:   };
87:   const pct = { hp: 0, mp: 0 };
88:   const eleRes = { fire: 0, frost: 0, storm: 0, nature: 0, shadow: 0, earth: 0, water: 0, holy: 0 };
89:   const extras = { crit: 0, evade: 0, lifesteal: 0, counter: 0, mpRegen: 0, stormBoost: 0, reviveOnce: false };
90:   const tree = cls.tree;
91:   for (const node of tree) {
92:     if (!member.learned?.includes(node.id)) continue;
93:     const sk = SKILLS[node.id];
94:     if (!sk?.passive) continue;
95:     if (sk.mods) for (const [k, v] of Object.entries(sk.mods)) {
96:       if (k === 'hpPct') pct.hp += v;
97:       else if (k === 'mpPct') pct.mp += v;
98:       else if (k === 'crit') extras.crit += v;
99:       else if (k === 'evade') extras.evade += v;
100:       else if (k === 'fireRes') eleRes.fire += v;
101:       else if (k === 'lifesteal') extras.lifesteal += v;
102:       else if (s[k] !== undefined) s[k] += v;
103:     }
104:     if (sk.special === 'reviveOnce') extras.reviveOnce = true;
105:     if (sk.special === 'counter') extras.counter += .35;
106:     if (sk.special === 'counter25') extras.counter += .25;
107:     if (sk.special === 'lifesteal') extras.lifesteal += .18;
108:     if (sk.special === 'mpRegen') extras.mpRegen += 4;
109:     if (sk.special === 'mpRegen2') extras.mpRegen += 3;
110:     if (sk.special === 'stormBoost') extras.stormBoost += .2;
111:   }
112:   if (member.id === 'hero') {
113:     const o = ORIGINS[member.origin || state.heroOrigin];
114:     if (o?.bonuses) {
115:       for (const [k, v] of Object.entries(o.bonuses)) {
116:         if (k === 'hpPct') pct.hp += v;
117:         else if (s[k] !== undefined) s[k] += v;
118:       }
119:     }
120:   }
121:   if (member.bonus) for (const [k, v] of Object.entries(member.bonus)) { if (s[k] !== undefined) s[k] += v; }
122:   // equipment
123:   for (const slot of ['weapon', 'charm']) {
124:     const gid = member.gear?.[slot];
125:     const gi = gid && ITEMS[gid];
126:     if (gi?.stats) for (const [k, v] of Object.entries(gi.stats)) {
127:       if (k === 'hp' || k === 'mp') s[k] += v;
128:       else if (s[k] !== undefined) s[k] += v;
129:     }
130:   }
131:   s.hp = Math.round(s.hp * (1 + pct.hp));
132:   s.mp = Math.round(s.mp * (1 + pct.mp));
133:   for (const k of Object.keys(s)) s[k] = Math.round(s[k]);
134:   s.maxHp = s.hp;
135:   s.maxMp = s.mp;
136:   s.crit = .05 + s.luck * .004 + extras.crit;
137:   s.evade = Math.min(.35, s.agi * .002 + extras.evade);
138:   s.lifesteal = Math.min(.5, extras.lifesteal);
139:   s.counter = Math.min(.6, extras.counter);
140:   s.mpRegen = extras.mpRegen;
141:   s.stormBoost = extras.stormBoost;
142:   s.reviveOnce = extras.reviveOnce;
143:   s.eleRes = eleRes;
144:   return s;
145: }
