225:   base *= rnd(.9, 1.1);
226:   base *= elementMod(attacker, target, opts.element);
227:   if (hasStatus(target, 'mark')) base *= 1.25;
228:   if (target.guard) base *= .55;
229:   if (opts.execute && target.hp / target.maxHp < .35) base *= 2;
230:   const critChance = Math.min(.75, (attacker.stats?.crit || 0) + (opts.critBonus || 0));
231:   const crit = Math.random() < critChance;
232:   if (crit) base *= 1.7;
233:   return { dmg: Math.max(1, Math.round(base)), crit };
234: }
235: 
236: function applyDamage(source, target, amount, opts = {}) {
237:   if (!target || target.dead) return 0;
238:   let dmg = Math.max(0, Math.round(amount));
239:   // Aegis shields absorb first
240:   const shield = target.statuses.find((s) => s.id === 'shield' && (s.value || 0) > 0);
241:   if (shield) {
242:     const absorbed = Math.min(shield.value, dmg);
243:     shield.value -= absorbed;
244:     dmg -= absorbed;
245:     if (absorbed > 0) floater(target, `⛨ ${absorbed}`, '#8fd8c8');
246:     if (shield.value <= 0) removeStatus(target, 'shield');
247:   }
248:   target.fx.hitAt = now();
249:   if (dmg <= 0) return 0;
250:   target.hp = Math.max(0, target.hp - dmg);
251:   floater(target, `-${dmg}`, opts.crit ? '#ffd27a' : '#ff8f78', opts.crit);
252:   if (opts.crit) {
253:     audio.sfx('crit');
254:     shake(9);
255:     flash('#ffd9a8');
256:   } else {
257:     audio.sfx('hit');
258:   }
259:   // lifesteal
260:   const steal = source?.stats?.lifesteal || 0;
261:   if (steal > 0 && source && !source.dead) {
262:     const heal = Math.max(1, Math.round(dmg * steal));
263:     source.hp = Math.min(source.maxHp, source.hp + heal);
264:     floater(source, `+${heal}`, '#9fe0a8');
265:   }
266:   if (target.hp <= 0) killUnit(target);
267:   return dmg;
268: }
269: 
270: function killUnit(unit) {
271:   if (unit.dead) return;
272:   unit.dead = true;
273:   unit.deadAt = now();
274:   unit.statuses = [];
275:   unit.guard = false;
276:   pushLog(`<b>${unit.name}</b> falls.`, 'dmg');
277:   audio.sfx('defeat');
278: }
