280: // ── battle setup ───────────────────────────────────────────────
281: export async function startBattle({ zone, enemies = [], boss = false, bossName = null, canFlee = true } = {}) {
282:   if (battleState.active) return { victory: false, busy: true };
283:   battleState.active = true;
284:   battleState.zone = zone || { id: 'emberfield', name: 'Emberfield', ambient: 'plains' };
285:   battleState.boss = !!boss;
286:   battleState.bossName = bossName || (boss ? 'CALAMITY' : '');
287:   battleState.canFlee = canFlee && !boss;
288:   battleState.log = [];
289:   battleState.effects = [];
290:   battleState.floaters = [];
291:   battleState.round = 1;
292:   battleState.turnIndex = 0;
293:   battleState.activeUid = null;
294:   battleState.targetUid = null;
295:   battleState.result = null;
296:   battleState.phase = 'start';
297:   battleState.shakeUntil = 0;
298:   battleState.flashUntil = 0;
299:   battleState.allies = state.party.map((m, i) => makeAlly(m, i));
300:   battleState.enemies = enemies.map((e, i) => makeEnemy(e, i)).filter(Boolean);
301:   battleState.order = [];
302:   syncMembers();
303:   uiBattle.showBattleUI(battleState);
304:   audio.setScene(boss ? 'boss' : 'battle');
305:   if (boss) audio.sfx('magic');
306:   if (boss && battleState.bossName) pushLog(`<b>${battleState.bossName}</b> bars the way.`, 'dmg');
307:   uiBattle.syncBattleUI();
308:   await sleep(boss ? 650 : 420);
309:   const result = await runBattleLoop();
310:   return result;
311: }
312: 
313: async function runBattleLoop() {
314:   while (battleState.active) {
315:     buildOrder();
316:     battleState.round = battleState.round || 1;
317:     uiBattle.syncBattleUI();
318:     for (let qi = 0; qi < battleState.order.length; qi++) {
319:       if (battleState.result) break;
320:       const unit = unitByUid(battleState.order[qi]);
321:       if (!unit || unit.dead) continue;
322:       battleState.turnIndex = qi;
323:       battleState.activeUid = unit.uid;
324:       battleState.targetUid = null;
325:       battleState.phase = 'turn';
326:       uiBattle.syncBattleUI();
327:       const canAct = await beginTurn(unit);
328:       if (battleState.result) break;
329:       if (canAct && !unit.dead) {
330:         if (unit.side === 'ally') {
331:           battleState.phase = 'select';
332:           uiBattle.syncBattleUI();
333:           const action = await uiBattle.requestPlayerAction(unit);
334:           await executeAction(unit, action);
335:         } else {
336:           battleState.phase = 'enemy';
337:           uiBattle.syncBattleUI();
338:           await sleep(420);
339:           const action = chooseEnemyAction(unit);
340:           await executeAction(unit, action);
341:         }
342:       }
343:       if (battleState.result) break;
344:       await endOfTurn(unit);
345:       prune();
346:       syncMembers();
347:       checkEnd();
348:       uiBattle.syncBattleUI();
349:       await sleep(240);
350:       if (battleState.result) break;
351:     }
352:     if (battleState.result) break;
353:     battleState.round++;
354:     if (battleState.round > 99) {
355:       battleState.result = { defeat: true, respawn: true };
356:       break;
357:     }
358:   }
359:   return finishBattle(battleState.result);
360: }
361: 
362: function buildOrder() {
363:   const alive = [...battleState.allies, ...battleState.enemies].filter((u) => !u.dead);
364:   for (const u of alive) u.initiative = liveStat(u, 'agi') * rnd(.88, 1.14);
365:   alive.sort((a, b) => b.initiative - a.initiative);
366:   battleState.order = alive.map((u) => u.uid);
367:   battleState.turnIndex = -1;
368: }
