370: async function beginTurn(unit) {
371:   unit.guard = false;
372:   if (hasStatus(unit, 'stun')) {
373:     removeStatus(unit, 'stun');
374:     pushLog(`<b>${unit.name}</b> is stunned and loses the turn.`);
375:     floater(unit, 'STUNNED', '#b79bea');
376:     await sleep(420);
377:     return false;
378:   }
379:   if (unit.stats?.mpRegen > 0 && !unit.dead) {
380:     const before = unit.mp;
381:     unit.mp = Math.min(unit.maxMp, unit.mp + unit.stats.mpRegen);
382:     if (unit.mp > before) floater(unit, `+${unit.mp - before} MP`, '#8fc4ee');
383:   }
384:   return true;
385: }
386: 
387: async function endOfTurn(unit) {
388:   if (!unit || unit.dead) return;
389:   const maxHp = unit.maxHp;
390:   if (hasStatus(unit, 'burn')) {
391:     const dmg = Math.max(2, Math.round(maxHp * .06));
392:     applyDamage(null, unit, dmg, { noCounter: true });
393:     pushLog(`<b>${unit.name}</b> burns for ${dmg}.`, 'dmg');
394:     effect(unit, 'fire', 460);
395:   }
396:   if (unit.dead) return;
397:   if (hasStatus(unit, 'poison')) {
398:     const dmg = Math.max(2, Math.round(maxHp * .05));
399:     applyDamage(null, unit, dmg, { noCounter: true });
400:     pushLog(`<b>${unit.name}</b> suffers poison for ${dmg}.`, 'dmg');
401:     effect(unit, 'nature', 460);
402:   }
403:   if (unit.dead) return;
404:   if (hasStatus(unit, 'regen')) {
405:     const heal = Math.max(4, Math.round(unit.stats.mag * .75 + 8));
406:     unit.hp = Math.min(maxHp, unit.hp + heal);
407:     floater(unit, `+${heal}`, '#9fe0a8');
408:     effect(unit, 'heal', 420);
409:   }
410:   for (const st of unit.statuses) st.turns--;
411:   const expired = unit.statuses.filter((s) => s.turns <= 0);
412:   unit.statuses = unit.statuses.filter((s) => s.turns > 0);
413:   if (expired.length) {
414:     const names = expired.map((s) => s.name).join(', ');
415:     pushLog(`<b>${unit.name}</b>: ${names} fades.`, 'good');
416:   }
417:   // boss phase
418:   if (unit.def?.boss && !unit.enraged && unit.hp / unit.maxHp < .55) {
419:     unit.enraged = true;
420:     unit.stats.atk *= 1.16;
421:     unit.stats.mag *= 1.16;
422:     pushLog(`<b>${unit.name}</b> is undone by fury. Its power rises!`, 'dmg');
423:     floater(unit, 'ENRAGED', '#ff9a6a', true);
424:     effect(unit, 'shadow', 800);
425:     shake(10);
426:   }
427: }
