429: // ── enemy AI ───────────────────────────────────────────────────
430: function chooseEnemyAction(unit) {
431:   const moves = (unit.def.moves || []).map((id) => {
432:     const sk = SKILLS[id] || ENEMY_MOVES[id];
433:     return sk ? { id, ...sk } : null;
434:   }).filter(Boolean);
435:   const foes = living(opponents(unit));
436:   const hurt = unit.hp / unit.maxHp;
437:   const heals = moves.filter((m) => m.kind === 'heal' && (m.target === 'self' || m.target === 'ally' || m.target === 'allAllies'));
438:   if (hurt < .38 && heals.length && Math.random() < .7) {
439:     return { type: 'skill', skillId: heals[0].id, targetUid: unit.uid };
440:   }
441:   const buffs = moves.filter((m) => m.kind === 'buff' && m.target !== 'enemy');
442:   if (buffs.length && Math.random() < .18) {
443:     return { type: 'skill', skillId: pick(buffs).id, targetUid: unit.uid };
444:   }
445:   const attacks = moves.filter((m) => m.kind === 'phys' || m.kind === 'mag' || m.kind === 'buff');
446:   let target = pick(foes);
447:   const taunters = foes.filter((f) => hasStatus(f, 'taunt'));
448:   if (taunters.length && Math.random() < .72) target = pick(taunters);
449:   if (!target) return { type: 'attack', targetUid: null };
450:   if (attacks.length && Math.random() < .68) {
451:     const move = pick(attacks);
452:     return { type: 'skill', skillId: move.id, targetUid: target.uid };
453:   }
454:   return { type: 'attack', targetUid: target.uid };
455: }
