457: // ── action execution ───────────────────────────────────────────
458: async function executeAction(unit, action) {
459:   if (!action || unit.dead || battleState.result) return;
460:   battleState.targetUid = action.targetUid || null;
461:   uiBattle.syncBattleUI();
462:   if (action.type === 'guard') {
463:     unit.guard = true;
464:     addStatus(unit, 'defUp', 2);
465:     pushLog(`<b>${unit.name}</b> raises a guard.`, 'good');
466:     floater(unit, 'GUARD', '#78d5c0');
467:     effect(unit, 'buff', 440);
468:     audio.sfx('guard');
469:     await sleep(360);
470:     return;
471:   }
472:   if (action.type === 'flee') {
473:     await attemptFlee(unit);
474:     return;
475:   }
476:   if (action.type === 'item') {
477:     await useItem(unit, action);
478:     await sleep(280);
479:     return;
480:   }
481:   if (action.type === 'skill') {
482:     const sk = SKILLS[action.skillId] || ENEMY_MOVES[action.skillId];
483:     if (!sk || sk.passive) { await basicAttack(unit, action.targetUid); return; }
484:     const cost = sk.mp || 0;
485:     if (unit.side === 'ally' && unit.mp < cost) {
486:       pushLog(`<b>${unit.name}</b> lacks the aether for ${sk.name}.`, 'dmg');
487:       audio.sfx('error');
488:       await sleep(320);
489:       return;
490:     }
491:     if (cost) unit.mp = Math.max(0, unit.mp - cost);
492:     await useSkill(unit, { ...sk, id: action.skillId }, action.targetUid);
493:     await sleep(320);
494:     return;
495:   }
496:   await basicAttack(unit, action.targetUid);
497:   await sleep(240);
498: }
499: 
500: async function basicAttack(unit, targetUid) {
501:   let target = targetUid ? unitByUid(targetUid) : null;
502:   if (!target || target.dead) target = pick(living(opponents(unit)));
503:   if (!target) return;
504:   unit.fx.lungeAt = now();
505:   unit.fx.lungeDir = unit.side === 'ally' ? 1 : -1;
506:   pushLog(`<b>${unit.name}</b> strikes <b>${target.name}</b>.`);
507:   audio.sfx('hit');
508:   // evade
509:   const evade = Math.min(.4, (target.stats?.evade || 0) + (hasStatus(target, 'evade') ? .45 : 0));
510:   if (Math.random() < evade) {
511:     floater(target, 'MISS', '#b8b0a0');
512:     pushLog(`<b>${target.name}</b> slips aside.`, 'good');
513:     audio.sfx('miss');
514:     unit.fx.lungeAt = 0;
515:     return;
516:   }
517:   const { dmg, crit } = calcDamage(unit, target, { kind: 'phys', power: 1 });
518:   const dealt = applyDamage(unit, target, dmg, { crit });
519:   if (dealt > 0 && target.side === 'ally' && !target.dead && Math.random() < (target.stats.counter || 0)) {
520:     pushLog(`<b>${target.name}</b> answers the blow.`, 'good');
521:     floater(target, 'COUNTER', '#78d5c0');
522:     const c = calcDamage(target, unit, { kind: 'phys', power: .7 });
523:     await sleep(140);
524:     applyDamage(target, unit, c.dmg, { crit: c.crit });
525:   }
526: }
527: 
528: async function useSkill(unit, sk, targetUid) {
529:   const kind = sk.kind || 'phys';
530:   const element = sk.element || 'phys';
531:   const good = kind === 'heal' || kind === 'revive' || kind === 'buff' || kind === 'cleanse';
532:   pushLog(`<b>${unit.name}</b> uses <b>${sk.name}</b>.`, good ? 'good' : '');
533:   const fx = fxFor(element, kind);
534:   audio.sfx(sfxFor(element, kind));
535:   if (!good) flash(element === 'fire' ? '#ffb066' : element === 'storm' ? '#bfe0ff' : element === 'frost' ? '#d6f2ff' : '#ffe0bc');
536:   const friendsList = living(friends(unit));
537:   const foeList = living(opponents(unit));
538:   const enemiesOfUnit = opponents(unit);
539: 
540:   let targets = [];
541:   const explicit = targetUid ? unitByUid(targetUid) : null;
542:   switch (sk.target) {
543:     case 'self': targets = [unit]; break;
544:     case 'allAllies': targets = friendsList; break;
545:     case 'allEnemies': targets = foeList; break;
546:     case 'deadAlly': {
547:       const dead = friends(unit).filter((u) => u.dead);
548:       targets = explicit && explicit.dead ? [explicit] : (dead[0] ? [dead[0]] : []);
549:       break;
550:     }
551:     case 'ally': {
552:       const pool = kind === 'heal' ? friendsList : friendsList;
553:       targets = explicit && !explicit.dead && explicit.side === unit.side ? [explicit] : [pool[0] || unit];
554:       break;
555:     }
556:     case 'enemy':
557:     default: {
558:       let t = explicit && !explicit.dead && explicit.side !== unit.side ? explicit : null;
559:       if (!t) t = pick(foeList);
560:       targets = t ? [t] : [];
561:       break;
562:     }
563:   }
564:   if (sk.target === 'deadAlly' && !targets.length) {
565:     pushLog('No fallen ally answers the call.', 'dmg');
566:     return;
567:   }
568: 
569:   if (kind === 'heal') {
570:     const amount = Math.round(liveStat(unit, 'mag') * (sk.power || 1) * 1.65 + 10);
571:     for (const t of targets) {
572:       if (!t || t.dead) continue;
573:       const before = t.hp;
574:       t.hp = Math.min(t.maxHp, t.hp + amount);
575:       effect(t, 'heal', 620);
576:       floater(t, `+${t.hp - before}`, '#9fe0a8');
577:       pushLog(`<b>${t.name}</b> recovers ${t.hp - before} HP.`, 'heal');
578:     }
579:     return;
580:   }
581:   if (kind === 'revive') {
582:     for (const t of targets) {
583:       if (!t || !t.dead) continue;
584:       t.dead = false;
585:       t.deadAt = 0;
586:       t.hp = Math.max(1, Math.round(t.maxHp * (sk.power || .5)));
587:       t.statuses = [];
588:       effect(t, 'heal', 900);
589:       floater(t, 'REVIVED', '#8fe0c0', true);
590:       pushLog(`<b>${t.name}</b> returns to the fight.`, 'heal');
591:       audio.sfx('levelup');
592:     }
593:     return;
594:   }
595:   if (kind === 'cleanse') {
596:     for (const t of targets) {
597:       if (!t) continue;
598:       cleanseNegative(t);
599:       effect(t, 'heal', 500);
600:       floater(t, 'CLEANSED', '#8fd8c8');
601:       pushLog(`<b>${t.name}</b> is cleansed.`, 'good');
602:     }
603:     return;
604:   }
605:   if (kind === 'buff') {
606:     const statuses = sk.statuses || [];
607:     if (sk.target === 'enemy' || sk.target === 'allEnemies') {
608:       const list = sk.target === 'allEnemies' ? foeList : (targets.length ? targets : [pick(foeList)]).filter(Boolean);
609:       for (const t of list) {
610:         if (!t || t.dead) continue;
611:         for (const st of statuses) addStatus(t, st.id, st.turns, { value: st.value });
612:         effect(t, 'shadow', 520);
613:         floater(t, statuses.map((s) => STATUSES[s.id]?.icon || '✦').join(' '), '#b79bea');
614:         pushLog(`<b>${t.name}</b> is marked.`, 'good');
615:       }
616:       return;
617:     }
618:     for (const t of targets) {
619:       if (!t || t.dead) continue;
620:       for (const st of statuses) addStatus(t, st.id, st.turns, { value: st.value });
621:       effect(t, 'buff', 620);
622:       floater(t, statuses.map((s) => STATUSES[s.id]?.icon || '✦').join(' '), '#78d5c0');
623:       pushLog(`<b>${t.name}</b> is empowered.`, 'good');
624:     }
625:     return;
626:   }
627: 
628:   // physical / magical damage
629:   const hits = sk.hits || 1;
630:   const strike = async (target) => {
631:     if (!target || target.dead) return;
632:     const evade = Math.min(.38, (target.stats?.evade || 0));
633:     if (Math.random() < evade) {
634:       floater(target, 'MISS', '#b8b0a0');
635:       audio.sfx('miss');
636:       return;
637:     }
638:     const { dmg, crit } = calcDamage(unit, target, {
639:       kind, power: sk.power || 1, element, pierce: sk.pierce || 0,
640:       critBonus: sk.critBonus || 0, execute: sk.execute,
641:     });
642:     effect(target, fx, 620);
643:     const dealt = applyDamage(unit, target, dmg, { crit });
644:     if (sk.drain && dealt > 0) {
645:       const heal = Math.round(dealt * sk.drain);
646:       unit.hp = Math.min(unit.maxHp, unit.hp + heal);
647:       floater(unit, `+${heal}`, '#9fe0a8');
648:     }
649:     if (sk.status && !target.dead && Math.random() < (sk.status.chance || .3)) {
650:       addStatus(target, sk.status.id, sk.status.turns || 3);
651:       pushLog(`<b>${target.name}</b> is ${STATUSES[sk.status.id]?.name || 'afflicted'}.`, 'good');
652:     }
653:   };
654:   if (sk.randomHits) {
655:     for (let h = 0; h < hits; h++) {
656:       const pool = living(enemiesOfUnit);
657:       if (!pool.length) break;
658:       await strike(pick(pool));
659:       await sleep(100);
660:     }
661:   } else {
662:     for (const t of targets) {
663:       for (let h = 0; h < hits; h++) {
664:         if (!t || t.dead) break;
665:         await strike(t);
666:         await sleep(hits > 1 ? 110 : 60);
667:       }
668:     }
669:   }
670:   if (targets.some((t) => t?.def?.boss)) shake(8);
671: }
672: 
673: async function useItem(unit, action) {
674:   const item = ITEMS[action.itemId];
675:   if (!item || (state.inventory[action.itemId] || 0) <= 0) {
676:     pushLog('The satchel is empty.', 'dmg');
677:     return;
678:   }
679:   state.inventory[action.itemId]--;
680:   if (state.inventory[action.itemId] <= 0) delete state.inventory[action.itemId];
681:   pushLog(`<b>${unit.name}</b> uses <b>${item.name}</b>.`, 'good');
682:   if (item.flee) {
683:     await attemptFlee(unit, .9);
684:     if (!battleState.result) pushLog('The smoke thins. There is no way out.', 'dmg');
685:     return;
686:   }
687:   if (item.bomb) {
688:     for (const t of living(battleState.enemies)) {
689:       effect(t, 'fire', 700);
690:       const dmg = Math.round((item.power || 70) * elementMod(unit, t, item.element));
691:       applyDamage(unit, t, dmg, {});
692:       await sleep(90);
693:     }
694:     flash('#ffb066');
695:     return;
696:   }
697:   const targetUid = action.targetUid;
698:   let target = targetUid ? unitByUid(targetUid) : null;
699:   if (item.target === 'deadAlly') {
700:     const dead = battleState.allies.filter((u) => u.dead);
701:     target = target && target.dead ? target : dead[0];
702:     if (target) {
703:       target.dead = false;
704:       target.hp = Math.max(1, Math.round(target.maxHp * (item.revive || .45)));
705:       target.statuses = [];
706:       effect(target, 'heal', 800);
707:       floater(target, 'REVIVED', '#8fe0c0', true);
708:       pushLog(`<b>${target.name}</b> returns to the fight.`, 'heal');
709:     }
710:     return;
711:   }
712:   if (!target || target.dead) target = item.target === 'self' ? unit : battleState.allies.filter((u) => !u.dead)[0];
713:   if (!target) return;
714:   if (item.cleanse) {
715:     cleanseNegative(target);
716:     effect(target, 'heal', 460);
717:     floater(target, 'CLEANSED', '#8fd8c8');
718:   }
719:   if (item.heal) {
720:     const before = target.hp;
721:     target.hp = Math.min(target.maxHp, target.hp + item.heal);
722:     effect(target, 'heal', 620);
723:     floater(target, `+${target.hp - before}`, '#9fe0a8');
724:   }
