229: // ── skills ────────────────────────────────────────────────────
230: function renderSkills(box) {
231:   const m = memberOf();
232:   if (!m) return;
233:   const cls = CLASSES[m.classId];
234:   const avail = availableNodes(m).map((n) => n.id);
235:   const tiers = 5;
236:   const cells = [];
237:   for (let tier = 0; tier < tiers; tier++) {
238:     for (let col = 0; col < 3; col++) {
239:       const node = cls.tree.find((n) => n.tier === tier && n.col === col);
240:       cells.push(node ? node : null);
241:     }
242:   }
243:   box.innerHTML = `
244:     ${charTabs()}
245:     <div class="skill-top">
246:       <div class="menu-section-title" style="margin:0">${cls.name} <small>${cls.role} · ${cls.weapon}</small></div>
247:       <div class="skill-pool">Skill points <b>${m.sp}</b></div>
248:     </div>
249:     <div class="tree-wrap">
250:       <div class="tree-grid" id="tree-grid">
251:         ${cells.map((node) => {
252:           if (!node) return '<div style="min-height:1px"></div>';
253:           const learned = m.learned.includes(node.id);
254:           const can = !learned && avail.includes(node.id) && m.sp >= node.sp;
255:           const clsName = learned ? 'learned' : can ? 'available' : 'locked';
256:           const kind = node.kind === 'passive' ? 'Passive' : 'Active';
257:           return `<button class="tree-node ${clsName} ${selectedNode === node.id ? 'just' : ''}" data-node="${node.id}">
258:             <span class="tn-icon">${node.icon}</span>
259:             <span class="tn-name">${escapeHtml(node.name)}</span>
260:             <span class="tn-kind">${kind} · tier ${node.tier + 1}</span>
261:             <span class="tn-cost">${learned ? 'Learned' : node.sp + ' SP'}</span>
262:             <span class="tn-desc">${escapeHtml(node.desc)}</span>
263:           </button>`;
264:         }).join('')}
265:       </div>
266:     </div>
267:     <div class="tree-legend">
268:       <span><i class="dot" style="background:#78d5c0"></i><b>Learned</b></span>
269:       <span><i class="dot" style="background:#f0a15a"></i><b>Available</b></span>
270:       <span><i class="dot" style="background:#3d4452"></i><b>Locked</b></span>
271:       <span>Tap a node to inspect. Learning is permanent.</span>
272:     </div>
273:     <div id="skill-detail" class="skill-detail ${selectedNode ? 'show' : ''}"></div>`;
274:   bindCharTabs(box);
275:   drawTreeLines();
276:   const detail = $('#skill-detail');
277:   if (selectedNode) {
278:     const node = cls.tree.find((n) => n.id === selectedNode);
279:     if (node) {
280:       const learned = m.learned.includes(node.id);
281:       const can = !learned && avail.includes(node.id) && m.sp >= node.sp;
282:       detail.innerHTML = `<h4>${node.icon} ${escapeHtml(node.name)} <span class="sd-cost">${learned ? 'LEARNED' : node.sp + ' SKILL POINT' + (node.sp > 1 ? 'S' : '')}</span></h4>
283:         <p>${escapeHtml(node.desc)}</p>
284:         <div class="sd-actions">
285:           ${learned ? '<span style="font-size:10px;color:var(--teal);align-self:center">This path is already yours.</span>' : can ? `<button class="btn primary" id="btn-learn">Learn</button>` : `<span style="font-size:10px;color:var(--ink-faint);align-self:center">${avail.includes(node.id) ? 'Not enough skill points.' : 'Requires ' + (node.req || []).map((r) => SKILLS[r]?.name || r).join(', ')}</span>`}
286:           <button class="btn ghost" id="btn-node-close">Close</button>
287:         </div>`;
288:       const learn = $('#btn-learn');
289:       if (learn) learn.onclick = () => {
290:         if (learnNode(m, node.id)) {
291:           audio.sfx('levelup');
292:           toast(`Learned ${node.name}`, '✦');
293:           renderSkills(box);
294:         } else { audio.sfx('error'); toast('Cannot learn that yet.', '!'); }
295:       };
296:       $('#btn-node-close').onclick = () => { selectedNode = null; detail.classList.remove('show'); };
297:     }
298:   }
299:   box.querySelectorAll('[data-node]').forEach((b) => {
300:     b.onclick = () => { selectedNode = selectedNode === b.dataset.node ? null : b.dataset.node; audio.sfx('click'); renderSkills(box); };
301:   });
