304: function drawTreeLines() {
305:   requestAnimationFrame(() => {
306:     const grid = $('#tree-grid');
307:     if (!grid) return;
308:     const nodes = [...grid.querySelectorAll('[data-node]')];
309:     if (!nodes.length) return;
310:     const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
311:     svg.setAttribute('class', 'tree-lines');
312:     svg.setAttribute('width', grid.scrollWidth);
313:     svg.setAttribute('height', grid.scrollHeight);
314:     svg.setAttribute('viewBox', `0 0 ${grid.scrollWidth} ${grid.scrollHeight}`);
315:     const center = (node) => ({
316:       x: node.offsetLeft + node.offsetWidth / 2,
317:       y: node.offsetTop + node.offsetHeight / 2,
318:     });
319:     for (const nodeEl of nodes) {
320:       const node = memberOf()?.classId ? CLASSES[memberOf().classId].tree.find((n) => n.id === nodeEl.dataset.node) : null;
321:       if (!node) continue;
322:       const to = center(nodeEl);
323:       for (const reqId of node.req || []) {
324:         const reqEl = grid.querySelector(`[data-node="${reqId}"]`);
325:         if (!reqEl) continue;
326:         const from = center(reqEl);
327:         const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
328:         path.setAttribute('d', `M ${from.x} ${from.y} C ${from.x} ${(from.y + to.y) / 2}, ${to.x} ${(from.y + to.y) / 2}, ${to.x} ${to.y}`);
329:         path.setAttribute('fill', 'none');
330:         path.setAttribute('stroke', 'rgba(240,178,122,.22)');
331:         path.setAttribute('stroke-width', '1.4');
332:         svg.appendChild(path);
333:       }
334:     }
335:     grid.insertBefore(svg, grid.firstChild);
336:   });
337: }
