413: function useOutOfBattle(id) {
414:   const it = ITEMS[id];
415:   const m = memberOf();
416:   if (!it || !m) return;
417:   if (it.target === 'deadAlly') {
418:     const dead = state.party.find((x) => x.hp <= 0);
419:     if (!dead) { toast('No one has fallen.', '☤'); audio.sfx('error'); return; }
420:     dead.hp = Math.max(1, Math.round(statBlock(dead).maxHp * (it.revive || .45)));
421:   } else if (it.heal || it.mp || it.cleanse) {
422:     const st = statBlock(m);
423:     if (it.heal) m.hp = Math.min(st.maxHp, m.hp + it.heal);
424:     if (it.mp) m.mp = Math.min(st.maxMp, m.mp + it.mp);
425:     if (it.cleanse) { /* no persistent statuses outside battle */ }
426:   } else if (it.flee) {
427:     state.repelSteps = 120;
428:     toast('The smoke will keep weak foes away for 120 steps.', '☾');
429:   } else if (it.bomb) {
430:     toast('Save the fire flask for a fight.', '✹'); audio.sfx('error'); return;
431:   } else {
432:     audio.sfx('error'); return;
433:   }
434:   removeItem(id, 1);
435:   audio.sfx('heal');
436:   toast(`${it.name} used.`, it.icon || '❖');
437:   renderItems($('#menu-content'));
438: }
