440: function sellItem(id) {
441:   const it = ITEMS[id];
442:   if (!it) return;
443:   const price = Math.max(1, Math.floor((it.price || 0) * SELL_RATE));
444:   if (it.type === 'gear') {
445:     const idx = state.gearOwned.indexOf(id);
446:     if (idx === -1) { toast('That gear is equipped.', '!'); audio.sfx('error'); return; }
447:     state.gearOwned.splice(idx, 1);
448:   } else {
449:     if (!removeItem(id, 1)) return;
450:   }
451:   addGold(price);
452:   audio.sfx('chest');
453:   toast(`Sold ${it.name} for ${price} g.`, '❖');
454:   selectedItem = null;
455:   renderItems($('#menu-content'));
456: }
