378:     const p = eff.uid ? positions.get(eff.uid) : null;
379:     drawEffect(ctx, eff, W, H, now, p);
380:   }
381: 
382:   // target line / cursor ring for target round handled by DOM list too
383: 
384:   // floaters
385:   for (const f of battle.floaters) {
386:     const age = now - f.born;
387:     if (age < 0 || age > f.dur) continue;
388:     const p = positions.get(f.uid);
389:     if (!p) continue;
390:     const k = age / f.dur;
391:     const x = p.x + (f.dx || 0) + (f.vx || 0) * k;
392:     const y = p.y - p.s * .9 - k * 46 + (f.dy || 0);
393:     ctx.save();
394:     ctx.font = `700 ${f.big ? Math.max(16, s * .34) : Math.max(11, s * .22)}px Georgia, serif`;
395:     ctx.textAlign = 'center';
396:     ctx.shadowColor = '#000'; ctx.shadowBlur = 7;
397:     ctx.globalAlpha = clamp(1.4 - k * 1.4, 0, 1);
398:     ctx.fillStyle = f.color || '#f0e3cf';
399:     ctx.fillText(f.text, x, y);
400:     ctx.restore();
401:   }
402:   ctx.restore();
403: 
404:   // screen flash
405:   if (battle.flashUntil > now) {
406:     const k = (battle.flashUntil - now) / 240;
407:     ctx.fillStyle = withAlpha(battle.flashColor || '#ffd9a8', clamp(k, 0, .65));
408:     ctx.fillRect(0, 0, W, H);
409:   }
410:   // dark vignette top/bottom
411:   const vg = ctx.createLinearGradient(0, 0, 0, H);
412:   vg.addColorStop(0, 'rgba(4,6,10,.32)');
413:   vg.addColorStop(.22, 'rgba(4,6,10,0)');
414:   vg.addColorStop(.72, 'rgba(4,6,10,0)');
415:   vg.addColorStop(1, 'rgba(4,6,10,.5)');
416:   ctx.fillStyle = vg; ctx.fillRect(0, 0, W, H);
417: 
418:   if (battle.boss) {
419:     ctx.save();
420:     ctx.font = `600 ${Math.max(9, W * .012)}px "Avenir Next", system-ui, sans-serif`;
421:     ctx.fillStyle = 'rgba(255,180,120,.45)';
422:     ctx.textAlign = 'center';
423:     ctx.letterSpacing = '4px';
424:     ctx.fillText(battle.bossName || 'CALAMITY', W / 2, H * .08);
425:     ctx.restore();
426:   }
427: }
